硬 體 設 序 , 帶 動 地 方 觀光 產業 的 發 展 。9. 積極 爭取 推 動 頭 分 、 湖 西 、 湖 東 等 社區 農村 再 生 土地 重 劃 工 程 。10. 透
過 枕 山 農村 社區 土地 重 劃 , 辦 理 宣 19 線 ( 枕 山 路 ) 截 彎 取 直 道 路 改善 工程 。11. 全 面 汰 換 本 鄉 各 村 路 燈 為 LED 燈 ,
提昇 照明 , 增 進 行 車 安全 。12. 辦理 本 鄉 重 要 路 口 增設 24 小 時 監視 系 統 , 強 化 地 方 治安 , 維 護 社 區 安全 。13. 爭
取 籌 設 本 鄉 溫泉 休閒 專業 區 , 促 進 地 方 經 濟 及 觀光 產業 發 展 。14. 建 請 蘭 陽 溪 左 岸 高 灘地 (中 華 、 蓁 巷 、 七 賢 、
深溝 堤 段 ) 建 設 為 觀光 遊憩 休閒 帶 。15. 爭取 經 費 辦 理大 湖 溪 後 續 維 護 改善 工程 。16. 建議 河川 主 管 機 關於 轄 內 堤
防 道路 增設 照明 路 燈 , 便 利 民 眾 通行 。17. 成 立 大 湖 風 景區 及 金 山 公 園 農 特 產品 展示 專區 。18. 重視 老人 營養 午
餐 , 增 添 設備 及 注重 餐 食 營 養 衛 生 , 使 長 者 午餐 問題 受到 完善 照料 。19. 成 立 本 鄉 老 人 日 照 中 心 , 重 視 老 人 居家
照護 、 長 照 服 務 , 結 緩 子女 的 負擔 。20. 補助 社區 守望 相 助 隊 及 其 他 班 隊 添 購 軟 硬 體 設備 及 辦理 各 項 活動 , 健 全
社區 發 展 。21. 加 強 辦理 社會 福利 服務 工作 , 使 鄉 內 老人 、 兒 童 、 肯 少年 、 婦 幼 、 身 障 者 等 弱勢 族群 權益 受到 保
障 。22. 爭取 經 費 購置 幼兒 教學 設備 , 提 昇 幼兒 園 教學 品 質 。29. 爭取 提高 生 育 津貼 、 托 育 補助 、 人 育兒 津 貼 之 額
度 , 激 勵 鄉親 勇於 生 育 。24. 關心 退休 員工 生 活 , 加 強 在 職員 工 福利 服務 , 提 昇 鄉 公 所 服務 品 質 。'::TEXT,
