     '「 鄉 政要 更 好 , 萬 榮 再 十 一 」
一 、 新 政治 、 新 風氣

(1) 讓 鄉 政 業 務 簡 便 有 效率 , 施 政 訊息 公開 又 透明 。

(2) 南 區 、 北 區 設立 行 動 辦 公 室 , 族 人 不 用 南北 奔波 。

(3) 鄉 內 重大 投資 開 發 , 應 取得 在 地 族人 了 了解, 同意 及 共同 參與 為 優先 。
二 、 欣 欣 萬 榮 、 老 幼 一 同

(1) 盤 點 鄉 內 閒置 空間 , 充 分 利用 及 活化 。

(2) 因 應 少子 化 , 編 列 預 算 補 助 生 育 津貼 。

(3) 提 升 托 育 量 能 , 推 動 幼 兒 園 幼 童 母語 教學 。

(4 協助 輔導 各 村 文 健 站 , 老 人 失 智 據點 (協會) 業務 推 展 。
三 、 多 元 萬 榮 、 人 才 回 龍

(1 每 年 規劃 運動 賽事 , 發 掘 運動 人 才 並 協助 其 發 展 。

(2) 推 廣 鄉 內 創新 和 傳統 技藝 , 傳 承 教學 。

(3) 鼓 勵 在 外 其 他 公 部 門 服務 子弟 返 鄉 服務 。
四 、 札 根 萬 榮 、 有 志 一 同

(1) 持 續 改善 各 村 農 路 及 基礎 建設 。

(2) 積 極 拓展 多 方 管 道 , 推 動 鄉 內 農產品 產銷 。'::TEXT,
     '「鄉政要更好 , 萬榮再十一」
一、 新政治、 新風氣

(1) 讓鄉政業務簡便有效率 , 施政訊息公開又透明。

(2) 南區、 北區設立行動辦公室 , 族人不用南北奔波。

(3) 鄉內重大投資開發 , 應取得在地族人了了解, 同意及共同參與為優先。
二、 欣欣萬榮、 老幼一同

(1) 盤點鄉內閒置空間 , 充分利用及活化。

(2) 因應少子化 , 編列預算補助生育津貼。

(3) 提升托育量能 , 推動幼兒園幼童母語教學。

(4 協助輔導各村文健站 , 老人失智據點 (協會) 業務推展。
三、 多元萬榮、 人才回龍

(1 每年規劃運動賽事 , 發掘運動人才並協助其發展。

(2) 推廣鄉內創新和傳統技藝 , 傳承教學。

(3) 鼓勵在外其他公部門服務子弟返鄉服務。
四、 札根萬榮、 有志一同

(1) 持續改善各村農路及基礎建設。

(2) 積極拓展多方管道 , 推動鄉內農產品產銷。'::TEXT,
