意見 , 保障部落農民、 為謀農民福利。

十、 恢復辦理賽德克放傳統祭典技藝賽活動 (配合布農運、 泰雅運 ) 及傳統射箭比賽。

十一、 向上級 ( 縣府、 中央 ) 爭取標準傳統射箭比賽場地 , 以利各項辦理活動順暢圓滿。

十二、 編列經費鼓勵全鄉優秀體育選手參加知名賽事 (如全國運動會、 亞運、 世錦賽、 奧運 ),
