     '延續 用 心 , 議 福 秀 林

逐步 推 動 秀 林 幸福 藍圖

一 、 提 升 推 動 本 鄉 社 會 福利 政策 ; 普 設 文 化 健康 站 與 關懷 據點 ; 整 合 社 福 資 源 網 絡 ; 增 設 完善 運動 休閒 場所 。

二 、 輔 導 鄉 民 考 取 專 業 證照 ; 健 全 部 落 安全 網 絡 ; 建 置 完 善之 鄉 政 推 廣 網 路 平台 ; 輔 導 立 案 社團 宗教 團體 健全 發 展 。

三 、 興 建 秀 林 鄉 行 政大 樓 與 體育 館 ; 結合 社區 營造 , 打 造 部 落 文 化 特 色 。

四 、 發 展 部 落 觀 光 產業 ; 完 善 部 落 路 燈 、 水 溝 、 農 業 用 路 等 基礎 設施 ; 積 極 推 動 建 置 部 落 納骨 設施 。

五 、 持 續 辦 理 鄉 長 與 民有 約 ; 落 實 青年 政策 成 立 青年 發 展 委 員 會 ; 落 實 部 落 環保 工作 。

六 、 提 升 鄉 內 運動 風氣 , 積 極 輔導 各 項 運 動 技 能 發 展 ; 積 極 成 立 與 協助 山 警 、 義 消 、 巡 守 隊 。

七 、 推 動 部 落 藝 文 活動 、 產 業 市 集 ; 輔 導 部 落 工藝 產業 轉 型 ; 拓 展 部 落 產銷 平台 、 活 化 部 落 閒 置 場 域 ; 提 升 地 方 產業 的 創 生 契機 。

八 、 積 極 輔導 部 落成 立 家 政 班 與 傳統 工藝 培訓 班 ; 推 動 多 元 文 化 創意 產業 輔導 班 , 提 振 部 落 產業 發 展 。

九 、 實 踐 精緻 歲 時 祭儀 ;, 培 育 部 落 文 史 人 才 ,; 推 動 族 語 保存 與 教材 編撰 ; 輔 導 各 校 與 社團 推 動 文 化 教育 與 文 化 特 色 。

十 、 開 設 多 元 文 化 課程 傳承 文 化 根植 部 落 ; 出 版 太 魯 闇 族 部 落 史 、 人 物 誌 , 追 尋 與 探討 文 化 發 展 脈絡 。

十 一 、 辦 理 各 項 農 業 培訓 課程 ; 結合 專業 機 關 / 團隊 , 提 升 農 產品 加 工 、 改 良 、 包 裝 、 推 廣 技術 ; 協 助 成 立 產銷 班 並 提供 農機
與 有 機 質 肥 料 補助 。

十 二 、 建 立 部 落 產 業 品 牌 形 象 與 擴大 辦理 產業 行 銷 活 動 ; 完 整 建 置 部 落 產 業 實 體 , 凸 顯 產業 特 色 。

十 三 、 積 極 協助 鄉 民 辦理 土地 增 劃 編 與 取得 所 有 權 及 其 他 土地 權益 保障 。

十 四 、 主 動 溝 通 協 調 太 魯 閣 國 家 公園 與 在 地 居民 的 權益 保障 問題 。'::TEXT,
     '延續用心 , 議福秀林

逐步推動秀林幸福藍圖

一、 提升推動本鄉社會福利政策 ; 普設文化健康站與關懷據點 ; 整合社福資源網絡 ; 增設完善運動休閒場所。

二、 輔導鄉民考取專業證照 ; 健全部落安全網絡 ; 建置完善之鄉政推廣網路平台 ; 輔導立案社團宗教團體健全發展。

三、 興建秀林鄉行政大樓與體育館 ; 結合社區營造 , 打造部落文化特色。

四、 發展部落觀光產業 ; 完善部落路燈、 水溝、 農業用路等基礎設施 ; 積極推動建置部落納骨設施。

五、 持續辦理鄉長與民有約 ; 落實青年政策成立青年發展委員會 ; 落實部落環保工作。

六、 提升鄉內運動風氣 , 積極輔導各項運動技能發展 ; 積極成立與協助山警、 義消、 巡守隊。

七、 推動部落藝文活動、 產業市集 ; 輔導部落工藝產業轉型 ; 拓展部落產銷平台、 活化部落閒置場域 ; 提升地方產業的創生契機。

八、 積極輔導部落成立家政班與傳統工藝培訓班 ; 推動多元文化創意產業輔導班 , 提振部落產業發展。

九、 實踐精緻歲時祭儀 ;, 培育部落文史人才 ,; 推動族語保存與教材編撰 ; 輔導各校與社團推動文化教育與文化特色。

十、 開設多元文化課程傳承文化根植部落 ; 出版太魯闇族部落史、 人物誌 , 追尋與探討文化發展脈絡。

十一、 辦理各項農業培訓課程 ; 結合專業機關 / 團隊 , 提升農產品加工、 改良、 包裝、 推廣技術 ; 協助成立產銷班並提供農機
與有機質肥料補助。

十二、 建立部落產業品牌形象與擴大辦理產業行銷活動 ; 完整建置部落產業實體 , 凸顯產業特色。

十三、 積極協助鄉民辦理土地增劃編與取得所有權及其他土地權益保障。

十四、 主動溝通協調太魯閣國家公園與在地居民的權益保障問題。'::TEXT,
