人 車 分 流 , 重視 用 路 人 安全 ; 充足 監視 器 、 垃 圾 車 收 運 更 完善 。

經 濟 振興 , 產 業 創新

產業 智慧 科技 導入 轉 型 ; 小 農 夫 作 、 小 農 履 歷 ; 數 位 行 負 三 大 商 圈 、 觀 光 包 裝 並 進 駐 觀 光 工 廠 。

文 教 經 營 , 接 軌 國 際

增加 圖 書 館 雙 語 、 數 位 館藏 ; 重視 特 教 受 教 權 、 體 育 教育 重點 發 展 、 培 養 教 練 師 資 、E 化 創新 多 元 教育 。

地 方 創 生 、 社 區 營造 , 活 化 南 機 場 、 福 州 巷 歷史 文 化 , 完 善 地 方 文 史 教 育 , 增 強 文 化 底蘊 。

在 地 文 化 國 際 化 , 增 加 國 際 交 流 機 會 ; 定 期 舉辦 市 集 、 主 題 活動 , 展 現 文 創 實力 。

支持 婦幼 , 親 子 友善

育兒 津貼 再 提高 、 提 高 公 托 收 托 率 、 簽 約 準 公 托 提 高 全 市 送 托 率 、 降 低 托 兒 所 幼兒 園 師 生 比 。

建設 親子 公園 、 室 內 親子 館 營造 親子 友善 城市 。

樂 齡 照護 , 社 區 共 好

與 社區 鄰里 活動 中 心 合作 充實 地 方 長 照 服 務 ; 增設 日 托 中 心 、 長 青 食堂; 增加 長 者 集 會 照護 據點 。

青年 力量 , 展 望 未 來

與 青年 團體 合作 , 共 同 推 動 宜蘭 市 政 ; 增 加 表 年 人 在 市 公所 比 例 , 整 體 政策 年 輕 化 。

深化 青年 創業 , 廣 邀 青 創 團隊 進 駐 與 青年 切磋 。'::TEXT,
