政見

建設升級 , 宣居城市

建設高速公路聯絡道 , 完善交通 ; 整治地面平整 , 水溝設即、 基礎建設再升級。

人車分流 , 重視用路人安全 ; 充足監視器、 垃圾車收運更完善。

經濟振興 , 產業創新

產業智慧科技導入轉型 ; 小農夫作、 小農履歷 ; 數位行負三大商圈、 觀光包裝並進駐觀光工廠。

文教經營 , 接軌國際

增加圖書館雙語、 數位館藏 ; 重視特教受教權、 體育教育重點發展、 培養教練師資、E 化創新多元教育。

地方創生、 社區營造 , 活化南機場、 福州巷歷史文化 , 完善地方文史教育 , 增強文化底蘊。

在地文化國際化 , 增加國際交流機會 ; 定期舉辦市集、 主題活動 , 展現文創實力。

支持婦幼 , 親子友善

育兒津貼再提高、 提高公托收托率、 簽約準公托提高全市送托率、 降低托兒所幼兒園師生比。

建設親子公園、 室內親子館營造親子友善城市。

樂齡照護 , 社區共好

與社區鄰里活動中心合作充實地方長照服務 ; 增設日托中心、 長青食堂; 增加長者集會照護據點。

青年力量 , 展望未來

與青年團體合作 , 共同推動宜蘭市政 ; 增加表年人在市公所比例 , 整體政策年輕化。

深化青年創業 , 廣邀青創團隊進駐與青年切磋。'::TEXT,
