     '1. 檢討本鄉易淹水地區排水系統及鄉內排水溝清淤並逐步解決 , 使鄉親免受淹水之苗。

2. 重視學章教育配合學校針對幸勢家庭學童編列獎助學金提供實質之協助。

3. 持續爭取鐵路高架化及建請中央規劃興建快速道路 , 以紓解本鄉交通瓶頸。

4. 視公所財政狀況檢討增加鄰長現有福利政策。

5. 結合農漁會團體 , 推廣行銷本鄉農漁特產增加農漁民收入。

6. 照顧老人福利持續發放 (65 歲以上 ) 老人重陽敬老禮金及辦理長青歌唱比賽活動。

7. 和爭取保生村海岸線綠帶規劃設置及枋寮漁港擴建提供鄉親一休閒遊著之處所。

8. 建請縣政府於原中央廣播電台場址土地建置養殖生產區海水供應中繼設施及農漁特產品產銷中心。

9. 建請中央於臺 1 線水底寮外環道 (中華路、 建興路、 三民路 ) 路口規劃建置陸橋以解決水底穴對外
交通堵塞問題。

10. 設置青年就業服務中心 , 協助輔導青年就業。

11. 爭取人台糖土地規劃做為運動公園及設置滯洪池 , 提供鄉親一休閒運動處所及防範水底寮三村水患
發生。

12. 辦理鄉之及青年街舞等運動賽事 , 以提升及帶動本鄉連動風氣。'::TEXT,
