十 一 、 繼 續 做 好 路 平 、 路 燈亮 、 水 溝通 。

十 二 、 五 結 排水 營造 花 樹 廊 道 , 實 現 休閒 運動 及 輕 旅遊 的 優質 勝地 ; 並 持續 規 畫 水 域 鴨 母 船 等 親水 新 體驗 。

十 三 、 持 續 推 動 二 結 王 公 廟 碳 過 火 、 利 澤 永 安 宮 走 起 及 廟宇 嘉年華 會 等 活動 , 增 進 民俗 年 節氣 氛 。

十 四 、 配 合 農田 水 利 署 以 地 盡 其 用 拓寬 農 路 , 促 進 農作 物 運 輸 及 用 路 人 安全 便捷 。

十 五 、 持 續 爭 取 表 仔 地 設 五 股 抽水 站 及 五 十 二 甲 溼 地 保育 利用 計 畫 。

十 六 、 爭 取 鄉 轄 宜 196 線 大 眾 路 段 及 宜 25 線 後 續 道 路 拓寬 改善 工程 。

十 七 、 高 鐵 站 建 置 , 爭 取 宜 蘭 市 環 道 與 羅 東 環 道 之 連接 , 力 促 於 五 結 鄉 規劃 專用 道路 , 結 解 平面 交通 瓶頸 。'::TEXT,
