三、 加強免費幸福巴士擴大延續服務區域範圍。

四、 落實結婚、 生育、 幼兒營養補助及幼童入學免抽籤 , 增建 8 間教保室 , 設才藝及英語教學專班 , 爭取補助學
費及餐費 , 減輕家長經濟負擔。

