十一、 繼續做好路平、 路燈亮、 水溝通。

十二、 五結排水營造花樹廊道 , 實現休閒運動及輕旅遊的優質勝地 ; 並持續規畫水域鴨母船等親水新體驗。

十三、 持續推動二結王公廟碳過火、 利澤永安宮走起及廟宇嘉年華會等活動 , 增進民俗年節氣氛。

十四、 配合農田水利署以地盡其用拓寬農路 , 促進農作物運輸及用路人安全便捷。

十五、 持續爭取表仔地設五股抽水站及五十二甲溼地保育利用計畫。

十六、 爭取鄉轄宜 196 線大眾路段及宜 25 線後續道路拓寬改善工程。

