     '林 聖 畫 市 長 政見

1. 路 平 、 燈 亮 、 水 溝通 。

2. 長 者 關懷 與 照顧 整體 規 畫 : 長 青 食堂 / 斗 六 市 老人 會 館 / 中 央 廚 房 建 置 / 廣 設 社區 關懷 據點 等 。

3. 打 造 運 動 城市 鄰里 公園 增設 各 類 連動 場所 : 膨 鼠 森林 公園 / 金 瓜 忌 公園 / 市 立 運 動 場 整 修 完 工 。

4. 劃 設 路 邊 停 車 格 並 設置 停車 場 。

5. 路 平 政 策 人 孔 蓋 下 地 鋪 柏 油 路 面 。

6. 圓 環 光 雕 水 舞 重 現 斗 六 風華 。

7. 建 立 路 口 監 視 系 統 , 科 技 執法 保障 斗 六 市 民生 命 財產 安全 。

8. 興 建 多 功能 社會 福利 大 樓 。

9. 斗 六 市 外 環 道 整治 / 提 升 道 路 品 質 , 重 要 機 關 聚 集 區 、 戶 外 人 文 活動 展演 場 , 以 '' 人 本 交通 環境 」, 串 聯 周 邊 重 要 景觀 據點 。
10. 食 農 教育 吃 當 李 : 公 所 從 源頭 落實 垃圾 減量 , 持 續 推 行 循環 經 濟 概念 。

11. 環 保 志 工 再 推 動 : 斗 六 市 現有 42 隊 環保 志 工 , 人 數 達 2151 人 , 暢 前 還 在 增加 中 , 上 比例 穫 登 雲 林 縣 之 完 。
12. 八 德 咎 命 園區 已 動工 整 建 中 型 簡易 靈堂 共 8 間 , 打 造 莊 賊 、 使 利 、 環 保 的 生 命 園區 。'::TEXT,
     '林聖畫市長政見

1. 路平、 燈亮、 水溝通。

2. 長者關懷與照顧整體規畫 : 長青食堂 / 斗六市老人會館 / 中央廚房建置 / 廣設社區關懷據點等。

3. 打造運動城市鄰里公園增設各類連動場所 : 膨鼠森林公園 / 金瓜忌公園 / 市立運動場整修完工。

4. 劃設路邊停車格並設置停車場。

5. 路平政策人孔蓋下地鋪柏油路面。

6. 圓環光雕水舞重現斗六風華。

7. 建立路口監視系統 , 科技執法保障斗六市民生命財產安全。

8. 興建多功能社會福利大樓。

9. 斗六市外環道整治 / 提升道路品質 , 重要機關聚集區、 戶外人文活動展演場 , 以 '' 人本交通環境」, 串聯周邊重要景觀據點。
10. 食農教育吃當李 : 公所從源頭落實垃圾減量 , 持續推行循環經濟概念。

11. 環保志工再推動 : 斗六市現有 42 隊環保志工 , 人數達 2151 人 , 暢前還在增加中 , 上比例穫登雲林縣之完。
12. 八德咎命園區已動工整建中型簡易靈堂共 8 間 , 打造莊賊、 使利、 環保的生命園區。'::TEXT,
