DO $repair$
DECLARE
    affected_count INTEGER;
BEGIN
    UPDATE public.person_claims AS claim
    SET
        claim_value = repair.normalized_source,
        claim_json = pg_catalog.jsonb_set(
            pg_catalog.jsonb_set(
                pg_catalog.jsonb_set(
                    pg_catalog.jsonb_set(
                        COALESCE(claim.claim_json, '{}'::JSONB),
                        '{platformText}',
                        pg_catalog.to_jsonb(repair.normalized_source),
                        TRUE
                    ),
                    '{items}',
                    repair.normalized_items,
                    TRUE
                ),
                '{contentSplit}',
                COALESCE(claim.claim_json -> 'contentSplit', '{}'::JSONB)
                    || pg_catalog.jsonb_build_object(
                        'reviewStatus',
                        'needs_review',
                        'releaseQuality',
                        pg_catalog.jsonb_build_object(
                            'version',
                            'platform-spacing-repair-20260907',
                            'reasonCodes',
                            pg_catalog.jsonb_build_array('source_review_required_after_spacing_repair')
                        )
                    ),
                TRUE
            ),
            '{platformQualityAudit}',
            COALESCE(claim.claim_json -> 'platformQualityAudit', '{}'::JSONB)
                || pg_catalog.jsonb_build_object(
                    'repairVersion',
                    'platform-spacing-repair-20260907',
                    'repair',
                    'normalized_fragmented_han_spacing'
                ),
            TRUE
        ),
        updated_at = pg_catalog.now()
    FROM platform_spacing_repairs AS repair
    WHERE claim.id = repair.id
      AND claim.claim_type = 'platform'
      AND COALESCE(claim.claim_json ->> 'platformText', claim.claim_value) = repair.old_source
      AND claim.claim_json #>> '{platformQualityAudit,classification}' = 'confirmed_spacing_issue';

    GET DIAGNOSTICS affected_count = ROW_COUNT;
    IF affected_count <> 113 THEN
        RAISE EXCEPTION 'Expected to normalize 113 platform records, updated %', affected_count;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM platform_spacing_repairs AS repair
        LEFT JOIN public.person_claims AS claim ON claim.id = repair.id
        WHERE claim.claim_value <> repair.normalized_source
           OR claim.claim_json ->> 'platformText' <> repair.normalized_source
           OR claim.claim_json -> 'items' <> repair.normalized_items
           OR claim.claim_json #>> '{contentSplit,reviewStatus}' <> 'needs_review'
           OR claim.claim_json #>> '{platformQualityAudit,repairVersion}'
                <> 'platform-spacing-repair-20260907'
    ) THEN
        RAISE EXCEPTION 'A platform spacing repair failed validation';
    END IF;
END
$repair$;

COMMIT;
